public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a visited array to keep track of the n-tersections that have been visited
    boolean[][] visited = new boolean[n][n];

    // Initialize a queue to perform BFS traversal of the n-tersections
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue and mark it as visited
    queue.add(start);
    visited[start[0]][start[1]] = true;

    // Perform BFS traversal until the queue is empty
    while (!queue.isEmpty()) {
        int[] current = queue.remove();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Iterate through the paths starting from the current n-tersection
        for (int[] path : paths) {
            int nextX = current[0] + path[0];
            int nextY = current[1] + path[1];

            // Ensure the next n-tersection is within the bounds of the n-teresting space
            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n) {
                // If the next n-tersection has not been visited, add it to the queue and mark it as visited
                if (!visited[nextX][nextY]) {
                    queue.add(new int[] {nextX, nextY});
                    visited[nextX][nextY] = true;
                }
            }
        }
    }

    // If the ending n-tersection was not found during the traversal, return "cannot be travelled"
    return "cannot be travelled";
}

